//! 🧪️ Original Pack stack backing and every logical root require independent caller authority.
use super::*;
use semio_framework_value::retained_clone::{RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep};
#[test]
fn pack_original_value_stack_storage_keeps_denied_owners_and_exact_physical_receipts(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for row in corpus["cases"].as_array().unwrap(){
  let limits=PackLimits{max_file_len:64,max_segment_len:16,max_symbols:1,max_depth:8,max_items:8,max_total_alloc:1<<20};
  let mut cursor=RetainedValueCursor::try_new(limits,1<<20).unwrap();
  let demand=cursor.storage_admission_demands().unwrap();
  let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};
  for axis in [0,1,2,4]{let mut denied=exact;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,_=>denied.maximum_depth=0};let before=cursor.progress();let(result,born,released)=crate::test_allocation::observe_backing(||cursor.admit_storage(denied).unwrap());assert_eq!(result,RetainedCloneProgress::default());assert_eq!((born,released),(0,0));assert_eq!(cursor.progress(),before);}
  let(receipt,born,released)=crate::test_allocation::observe_backing(||cursor.admit_storage(exact).unwrap());assert_eq!(born,demand.capacity_bytes);assert_eq!(receipt.retained_capacity_bytes,born);assert_eq!(released,0);
  for _ in 0..row["roots"].as_u64().unwrap(){cursor.grant().unwrap();}if row["pending"].as_bool().unwrap(){cursor.admit_byte(0,0).unwrap();}
  let mut stages=Vec::new();let mut physical=0;
  while !cursor.terminal_is_empty(){
   let stage=if cursor.pending.is_some(){"pending"}else if !cursor.stack.is_empty(){"frame"}else if cursor.allocated_bytes()!=0{"backing"}else{"complete"};
   let original=cursor.stack.as_ptr();let demand=cursor.storage_retirement_demands().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};
   for axis in [0,1,3,4]{if axis==3&&demand.release_bytes==0{continue;}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth=0};let before=cursor.progress();let(step,born,released)=crate::test_allocation::observe_backing(||cursor.retire_storage(denied).unwrap());assert_eq!(step,RetainedCloneStep::Progress(Default::default()));assert_eq!((born,released),(0,0));assert_eq!(cursor.progress(),before);assert_eq!(cursor.stack.as_ptr(),original);}
   let(step,born,released)=crate::test_allocation::observe_backing(||cursor.retire_storage(grant).unwrap());assert_eq!(born,0);let receipt=match step{RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt)=>receipt};assert_eq!(released,receipt.released_bytes);assert_eq!(receipt.copied_bytes,demand.copy_bytes);physical+=released;stages.push(stage);
  }
  assert_eq!(stages,row["close"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect::<Vec<_>>());assert_eq!(physical,born);let(_,born,released)=crate::test_allocation::observe_backing(||drop(cursor));assert_eq!((born,released),(0,0));
  eprintln!("[DEBUG] pack original storage roots={} born={} release={} terminal_drop=0",row["roots"],physical,physical);
 }
}

#[test]
fn pack_original_value_stack_storage_record_body_composes_real_children_for_every_prefix(){
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 for wire in corpus["recordBodies"].as_array().unwrap(){let wire=wire.as_str().unwrap();let bytes=(0..wire.len()).step_by(2).map(|index|u8::from_str_radix(&wire[index..index+2],16).unwrap()).collect::<Vec<_>>();let original=bytes.as_ptr();
  for stop in 0..=bytes.len(){let limits=PackLimits{max_file_len:64,max_segment_len:16,max_symbols:4,max_depth:8,max_items:16,max_total_alloc:1<<20};let mut cursor=RetainedRecordBodyCursor::try_new(limits,4,16,16,1<<20).unwrap();let mut born=0;
   for(index,byte)in bytes.iter().take(stop).enumerate(){
    for _ in 0..10000{if cursor.ingress_ready(){break}if cursor.next_allocation_bytes().unwrap().is_some(){let demand=cursor.record_storage_admission_demands().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};let(receipt,allocated,released)=crate::test_allocation::observe_backing(||cursor.admit_record_storage(grant).unwrap());assert_eq!(allocated,receipt.retained_capacity_bytes);assert_eq!(allocated,demand.capacity_bytes);assert_eq!(released,0);born+=allocated;}else{cursor.grant().unwrap();}}
    cursor.admit_byte(index as u64,*byte).unwrap();
   }
   assert_eq!(bytes.as_ptr(),original);let mut physical=0;
   for _ in 0..100000{if cursor.terminal_is_empty(){break}let demand=cursor.record_storage_retirement_demands(4096).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for axis in [0,1,2,3,4]{let amount=match axis{0=>1,1=>demand.copy_bytes,2=>demand.capacity_bytes,3=>demand.release_bytes,_=>demand.depth};if amount==0{continue}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1};let before=(cursor.allocated_bytes(),cursor.offset,cursor.pending,cursor.record_storage_retirement_demands(4096).unwrap());let(step,allocated,released)=crate::test_allocation::observe_backing(||cursor.retire_record_storage(4096,denied).unwrap());assert_eq!(step,RetainedCloneStep::Progress(Default::default()));assert_eq!((allocated,released),(0,0));assert_eq!((cursor.allocated_bytes(),cursor.offset,cursor.pending,cursor.record_storage_retirement_demands(4096).unwrap()),before);assert_eq!(bytes.as_ptr(),original);}let(step,allocated,released)=crate::test_allocation::observe_backing(||cursor.retire_record_storage(4096,grant).unwrap());let receipt=match step{RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt)=>receipt};assert_eq!(allocated,receipt.retained_capacity_bytes);assert_eq!(released,receipt.released_bytes);born+=allocated;physical+=released;}
   assert!(cursor.terminal_is_empty());assert_eq!(physical,born);let(_,allocated,released)=crate::test_allocation::observe_backing(||drop(cursor));assert_eq!((allocated,released),(0,0));assert_eq!(bytes.as_ptr(),original);
  }
 }
 eprintln!("[DEBUG] pack original RecordBody retains same pending byte/expectation/symbol child owners for every neutral prefix; all denied currencies zeroheap; exact complete physical conservation and terminalDrop0");
}

#[test]
fn pack_original_value_stack_storage_symbols_keep_each_partial_original_under_four_axes(){
 use crate::format::{RetainedPackSymbolTable,RetainedPackSymbolSpan};
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let texts=corpus["symbols"].as_array().unwrap().iter().map(|value|value.as_str().unwrap()).collect::<Vec<_>>();
 for stop in corpus["interruptions"].as_array().unwrap(){let stop=stop.as_u64().unwrap()as usize;let mut table=RetainedPackSymbolTable::try_new(4,16,8,1<<20).unwrap();let mut born=0;let mut consumed=0;
  while table.next_symbol_allocation_bytes(4,0).unwrap().is_some(){let demand=table.symbol_storage_admission_demands(4,0).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};for axis in [0,1,2,4]{let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,_=>denied.maximum_depth=0};let before=(table.len(),table.scalar_len(),table.allocated_bytes());let(receipt,allocated,released)=crate::test_allocation::observe_backing(||table.admit_symbol_storage(4,denied,0).unwrap());assert_eq!(receipt,Default::default());assert_eq!((allocated,released),(0,0));assert_eq!((table.len(),table.scalar_len(),table.allocated_bytes()),before);}let(receipt,allocated,released)=crate::test_allocation::observe_backing(||table.admit_symbol_storage(4,grant,0).unwrap());assert_eq!(allocated,demand.capacity_bytes);assert_eq!(allocated,receipt.retained_capacity_bytes);assert_eq!(released,0);born+=allocated;}
  'symbols:for text in &texts{let start=consumed;let mut utf8=0;for character in text.chars(){if consumed==stop{break 'symbols}while table.next_scalar_allocation_bytes(consumed+1,0).unwrap().is_some(){let demand=table.scalar_storage_admission_demands(consumed+1,0).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:0,maximum_depth:demand.depth};let(receipt,allocated,released)=crate::test_allocation::observe_backing(||table.admit_scalar_storage(consumed+1,grant,0).unwrap());assert_eq!(allocated,demand.capacity_bytes);assert_eq!(receipt.retained_capacity_bytes,allocated);assert_eq!(released,0);born+=allocated;}table.push_scalar_reserved(character,0).unwrap();utf8+=character.len_utf8();consumed+=1;}table.push_symbol_reserved(RetainedPackSymbolSpan{scalar_start:start as u64,scalar_len:(consumed-start)as u64,utf8_len:utf8 as u64},0).unwrap();}
  assert_eq!(consumed,stop);for(index,text)in texts.iter().take(table.len()).enumerate(){assert_eq!(table.symbol_chars(index as u64).unwrap(),text.chars().count());for(ordinal,character)in text.chars().enumerate(){assert_eq!(table.symbol_char(index as u64,ordinal).unwrap(),Some(character));}}
  let mut physical=0;for _ in 0..10000{if table.terminal_is_empty(){break}let demand=table.symbol_storage_retirement_demands(4096).unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:demand.copy_bytes,maximum_capacity_bytes:demand.capacity_bytes,maximum_release_bytes:demand.release_bytes,maximum_depth:demand.depth};for axis in [0,1,2,3,4]{let amount=match axis{0=>1,1=>demand.copy_bytes,2=>demand.capacity_bytes,3=>demand.release_bytes,_=>demand.depth};if amount==0{continue}let mut denied=grant;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,3=>denied.maximum_release_bytes-=1,_=>denied.maximum_depth-=1};let before=(table.len(),table.scalar_len(),table.allocated_bytes(),table.symbol_storage_retirement_demands(4096).unwrap());let(step,allocated,released)=crate::test_allocation::observe_backing(||table.retire_symbol_storage(4096,denied).unwrap());assert_eq!(step,RetainedCloneStep::Progress(Default::default()));assert_eq!((allocated,released),(0,0));assert_eq!((table.len(),table.scalar_len(),table.allocated_bytes(),table.symbol_storage_retirement_demands(4096).unwrap()),before);}let(step,allocated,released)=crate::test_allocation::observe_backing(||table.retire_symbol_storage(4096,grant).unwrap());let receipt=match step{RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt)=>receipt};assert_eq!(allocated,receipt.retained_capacity_bytes);assert_eq!(released,receipt.released_bytes);born+=allocated;physical+=released;}
  assert!(table.terminal_is_empty());assert_eq!(physical,born);let(_,allocated,released)=crate::test_allocation::observe_backing(||drop(table));assert_eq!((allocated,released),(0,0));eprintln!("[DEBUG] pack original partial Unicode symbols stop={stop} born={born} release={physical} terminal_drop=0");
 }
}

#[test]
fn pack_original_value_stack_storage_eager_capacity_retains_reserved_original_slots(){
 use semio_framework_value::{list::PagedList,retirement::controlled::ControlledRetirement};
 let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();
 let mut list=PagedList::<u64,16384>::empty();let mut born=0;let mut pointer=None;
 for target in corpus["capacityTargets"].as_array().unwrap(){let target=target.as_u64().unwrap()as usize;
  while let Some(capacity)=list.next_capacity_allocation_bytes(target).unwrap(){
   let copy=list.next_capacity_copy_byte_demand(target).unwrap();assert!(copy>0);let exact=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:capacity,maximum_release_bytes:0,maximum_depth:1};
   for axis in [0,1,2,4]{let mut denied=exact;match axis{0=>denied.maximum_items=0,1=>denied.maximum_copy_bytes-=1,2=>denied.maximum_capacity_bytes-=1,_=>denied.maximum_depth=0};let before=(list.len(),list.capacity(),list.allocated_bytes(),list.backing_ptr(0));let(receipt,allocated,released)=crate::test_allocation::observe_backing(||list.reserve_capacity_one_funded(target,denied).unwrap());assert_eq!(receipt,Default::default());assert_eq!((allocated,released),(0,0));assert_eq!((list.len(),list.capacity(),list.allocated_bytes(),list.backing_ptr(0)),before);}
   let(receipt,allocated,released)=crate::test_allocation::observe_backing(||list.reserve_capacity_one_funded(target,exact).unwrap());assert_eq!(allocated,capacity);assert_eq!(receipt.retained_capacity_bytes,allocated);assert_eq!(receipt.copied_bytes,copy);assert_eq!(released,0);born+=allocated;
  }
  assert!(list.capacity()>=target);if list.is_empty(){list.push_reserved(73).unwrap();pointer=list.backing_ptr(0)}assert_eq!(list.backing_ptr(0),pointer);assert_eq!(list.get(0),Some(&73));assert_eq!(list.len(),1);assert!(list.has_reserved_slot());
 }
 assert_eq!(list.next_capacity_copy_byte_demand(list.capacity()).unwrap(),0);let(_,allocated,released)=crate::test_allocation::observe_backing(||assert_eq!(list.reserve_capacity_one_funded(list.capacity(),Default::default()).unwrap(),Default::default()));assert_eq!((allocated,released),(0,0));
 let mut owner=match ControlledRetirement::new(list){Ok(owner)=>owner,Err((error,_))=>panic!("original list authority refused: {error}")};let mut physical=0;
 for _ in 0..10000{if owner.terminal_is_empty(){break}let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:owner.next_copy_byte_demand().unwrap(),maximum_capacity_bytes:owner.next_capacity_byte_demand(4096).unwrap(),maximum_release_bytes:owner.next_release_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand().unwrap()};let(step,allocated,released)=crate::test_allocation::observe_backing(||owner.step(grant).unwrap());let receipt=match step{RetainedCloneStep::Progress(receipt)|RetainedCloneStep::Complete(receipt)=>receipt};assert_eq!(allocated,receipt.retained_capacity_bytes);assert_eq!(released,receipt.released_bytes);born+=allocated;physical+=released;}
 assert!(owner.terminal_is_empty());assert_eq!(physical,born);let(_,allocated,released)=crate::test_allocation::observe_backing(||drop(owner));assert_eq!((allocated,released),(0,0));eprintln!("[DEBUG] pack original eager capacity1/513/8193 keeps live73 pointer while reserved slots exist born={born} release={physical} terminal_drop=0");
}
